const items = $input.all();
const headers = items[0].json.headers || {};
const body = items[0].json.body || items[0].json;
const rawKey = headers['x-context-key'] || '';
const apiKey = rawKey.replace(/[^a-f0-9]/gi, '');
return [{ json: { apiKey, body } }];

// ── Auth check ──
const auth = $('Auth Lookup').item.json;
if (!auth.home_scope || auth.home_scope === '__UNAUTHORIZED__') {
  return [{ json: { valid: false, error: 'Unauthorized: invalid API key' } }];
}
const homeScope = auth.home_scope;
const allowedScopes = Array.isArray(auth.allowed_scopes) ? auth.allowed_scopes : [];

const body = $('Extract Key').item.json.body;

const category = body.category;
const title = body.title;
const content = body.content;
const tags = body.tags || [];
const metadata = body.metadata || {};

if (!category || typeof category !== 'string' || category.trim() === '') {
  return [{ json: { valid: false, error: 'category is required and must be a non-empty string' } }];
}
if (!title || typeof title !== 'string' || title.trim() === '') {
  return [{ json: { valid: false, error: 'title is required and must be a non-empty string' } }];
}
if (!content || typeof content !== 'string' || content.trim() === '') {
  return [{ json: { valid: false, error: 'content is required and must be a non-empty string' } }];
}

// Determine write scope
let writeScope = homeScope;
let scopeExplicit = !!body.scope;
if (body.scope === 'shared' && allowedScopes.includes('shared')) {
  writeScope = 'shared';
} else if (body.scope && body.scope !== homeScope) {
  return [{ json: { valid: false, error: 'Cannot write to scope: ' + body.scope } }];
}

function esc(val) {
  if (val === null || val === undefined) return 'NULL';
  return "'" + String(val).replace(/'/g, "''") + "'";
}

function escArray(arr) {
  if (!Array.isArray(arr) || arr.length === 0) return "'{}'";
  const inner = arr.map(t => '"' + String(t).replace(/"/g, '\\"').replace(/'/g, "''") + '"').join(',');
  return "'{" + inner + "}'";
}

function escJson(obj) {
  if (!obj || typeof obj !== 'object') return "'{}'::jsonb";
  const jsonStr = JSON.stringify(obj).replace(/'/g, "''");
  return "'" + jsonStr + "'::jsonb";
}

const c = esc(category.trim());
const t = esc(title.trim());
const co = esc(content.trim());
const ta = escArray(tags);
const m = escJson(metadata);
const sc = esc(writeScope);

// On INSERT: use writeScope. On UPDATE: preserve existing scope unless explicitly set.
const scopeOnUpdate = scopeExplicit ? 'scope = EXCLUDED.scope,' : '';

const query = `INSERT INTO context_blocks (category, tags, title, content, metadata, scope) VALUES (${c}, ${ta}, ${t}, ${co}, ${m}, ${sc}) ON CONFLICT (category, title) DO UPDATE SET content = EXCLUDED.content, tags = EXCLUDED.tags, metadata = EXCLUDED.metadata, ${scopeOnUpdate} updated_at = now() RETURNING id, category, tags, title, content, metadata, scope, created_at, updated_at`;

return [{ json: { valid: true, query, content_raw: co, category_raw: c, title_raw: t, scope_raw: sc } }];

