// Matryoshka truncation: 4096d → 1024d + L2-normalize
const fullEmbedding = $input.first().json.embeddings[0];
const truncated = fullEmbedding.slice(0, 1024);
const norm = Math.sqrt(truncated.reduce((sum, x) => sum + x * x, 0));
const normalized = norm > 0 ? truncated.map(x => x / norm) : truncated;
return [{ json: { embeddings: [normalized], truncated_from: fullEmbedding.length, truncated_to: 1024 } }];

const embedding = $input.first().json.embeddings[0];
const dim = embedding.length;
const norm = Math.sqrt(embedding.reduce((sum, x) => sum + x * x, 0));
const isZeroVector = embedding.every(x => x === 0);
const mean = embedding.reduce((s, v) => s + v, 0) / dim;
const variance = embedding.reduce((sum, x) => sum + (x - mean) ** 2, 0) / dim;

if (isZeroVector || dim !== 1024 || norm < 0.9 || norm > 1.1 || variance < 0.0001) {
  throw new Error(`Embedding quality check failed: dim=${dim}, norm=${norm.toFixed(4)}, var=${variance.toFixed(6)}, zero=${isZeroVector}`);
}

return $input.all();

const items = $input.all();
const row = items[0].json;
return [{ json: { success: true, block: row } }];

